
import os
import sqlite3
from pathlib import Path
from html import escape

import streamlit as st


def _conexion():
    nombre = (
        "volley_chamar_publica.db"
        if os.environ.get("VOLLEY_PUBLICO") == "1"
        else "volley_chamar.db"
    )

    ruta = Path(nombre).resolve()

    return sqlite3.connect(
        ruta.as_uri() + "?mode=ro",
        uri=True
    )


def _numero(valor):
    return int(valor or 0)


def _porcentaje(numerador, denominador):
    if not denominador:
        return None

    return numerador / denominador


def _formato_porcentaje(valor):
    if valor is None:
        return "—"

    return f"{valor:.1f}%"


def _tarjeta(titulo, valor, descripcion):
    iconos = {
        "PARTIDOS ANALIZADOS": "📅",
        "RECEPCIONES TOTALES": "🏐",
        "RECEPCIÓN POSITIVA": "🎯",
        "ERRORES DE RECEPCIÓN": "⚠️",
        "DEFENSAS TOTALES": "🛡️",
        "CALIDAD DEFENSIVA": "📊",
    }

    icono = iconos.get(titulo, "🏐")
    destacada = " chv-libero-card-featured" if titulo == "PARTIDOS ANALIZADOS" else ""

    return f"""
    <div class="chv-libero-card{destacada}">
        <div class="chv-libero-card-title">
            <span class="chv-libero-card-icon">{icono}</span>
            {escape(titulo)}
        </div>
        <div class="chv-libero-card-value">
            {escape(str(valor))}
        </div>
        <div class="chv-libero-card-description">
            {escape(descripcion)}
        </div>
    </div>
    """


def mostrar_perfil_libero(jugador_id, temporada_id):

    with _conexion() as conexion:

        filas = conexion.execute(
            """
            SELECT
                p.id,
                ef.fundamento,
                ef.total_acciones,
                ef.errores,
                ef.porcentaje_positivo,
                ef.porcentaje_excelente
            FROM estadisticas_fundamento ef
            JOIN partidos p
                ON p.id = ef.partido_id
            WHERE ef.jugador_id = ?
              AND p.temporada_id = ?
              AND ef.fundamento IN ('Recepción', 'Defensa')
            ORDER BY p.jornada, p.fecha
            """,
            (jugador_id, temporada_id)
        ).fetchall()

    partidos_analizados = len({
        fila[0] for fila in filas
    })

    recepciones = 0
    errores_recepcion = 0
    defensas = 0

    recepcion_positiva_ponderada = 0.0
    recepciones_con_porcentaje = 0

    defensa_positiva_ponderada = 0.0
    defensas_con_porcentaje = 0

    for (
        partido_id,
        fundamento,
        acciones,
        errores,
        porcentaje_positivo,
        porcentaje_excelente
    ) in filas:

        total = _numero(acciones)

        if fundamento == "Recepción":

            recepciones += total
            errores_recepcion += _numero(errores)

            if porcentaje_positivo is not None and total > 0:
                recepcion_positiva_ponderada += (
                    total * porcentaje_positivo
                )
                recepciones_con_porcentaje += total

        elif fundamento == "Defensa":

            defensas += total

            if porcentaje_positivo is not None and total > 0:
                defensa_positiva_ponderada += (
                    total * porcentaje_positivo
                )
                defensas_con_porcentaje += total

    recepcion_positiva = _porcentaje(
        recepcion_positiva_ponderada,
        recepciones_con_porcentaje
    )

    calidad_defensiva = _porcentaje(
        defensa_positiva_ponderada,
        defensas_con_porcentaje
    )

    tarjetas = [
        (
            "PARTIDOS ANALIZADOS",
            partidos_analizados,
            "Encuentros con estadísticas de recepción o defensa."
        ),
        (
            "RECEPCIONES TOTALES",
            recepciones,
            "Acciones de recepción registradas."
        ),
        (
            "RECEPCIÓN POSITIVA",
            _formato_porcentaje(recepcion_positiva),
            "Porcentaje positivo registrado en Data Volley."
        ),
        (
            "ERRORES DE RECEPCIÓN",
            errores_recepcion,
            "Errores registrados en recepción."
        ),
        (
            "DEFENSAS TOTALES",
            defensas,
            "Acciones defensivas registradas."
        ),
        (
            "CALIDAD DEFENSIVA",
            _formato_porcentaje(calidad_defensiva),
            "Porcentaje positivo de defensa, si está disponible."
        ),
    ]

